import{_ as e,b as a,c as s,g as p}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"反馈回路与系统观","description":"","frontmatter":{"title":"反馈回路与系统观","author":"oasis","date":"2026-09-15T00:00:00.000Z","tags":["Date Log"]},"headers":[],"relativePath":"articles/essays/13.md","filePath":"articles/essays/13.md"}'),r={name:"articles/essays/13.md"};function i(_,t,o,n,d,c){return a(),s("div",null,[...t[0]||(t[0]=[p('<h2 id="反馈回路" tabindex="-1">反馈回路</h2><p>在我的记忆里，农村的自来水管都装在院子里，没有直接接入屋子。水管不进屋，是为了防止冬天冻裂；水瓮放在屋里，用来存饮用水。水瓮快见底时，就用水管接水。接水我总结了三个动作：塑料水管对接水龙头，用瓮盖压住塑料水管，打开水龙头。然后在一旁观察——掀开盖子，或听听水流的声音——时刻准备关闭水龙头。</p><p>在这样的场景里，我成了自来水系统的一部分：负责接收反馈、调节水龙头，从而形成了一个反馈回路。</p><p>一般来说，反馈回路包含三个要素：其一是目标（水瓮接满水），其二是检测设备（我充当检测设备），其三是反应机制（我关闭水龙头）。</p><h2 id="增强回路" tabindex="-1">增强回路</h2><p>人口发展与人口基数关系很大。基数小时，同样的生育率下人口规模变化平缓；基数大时，新生儿更多，增长曲线也更陡峭。</p><p>如果放任人口增长，不久就会接近资源容纳的饱和，反而不利于发展。这时会触发某种反馈回路，对增强回路进行调节。</p><p>设想世界资源无限，但 A 国与 B 国开战，且军事实力相当。这时，人口增强回路收益更大的国家，获胜概率也会更大。</p><p>从这两个例子可以看出：增强回路既可以产生正向收益，也可以产生负向收益。</p><h2 id="系统的特性和系统观" tabindex="-1">系统的特性和系统观</h2><p>《沙乡年鉴》的作者在「土地伦理」一章里，把土地共同体形象化为土地金字塔。这一伦理观念体现出整体主义的系统观：土地不是一堆资源的简单相加，而是不同分层结构所产生的能量循环。各层之间相互作用；人为干预会破坏层间关系，使整个系统无法动态平衡。因此人应当进入分层之中，依附于整个系统所带来的福祉。</p>',11)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
